const LDU_GROUP_A=['V50','V50 LITE','Y04','Y19S','Y29S','Y39'];
const LDU_GROUP_B=['V40 SE','V30 SE','V25','V25 E','V25E','Y36','Y28S','Y03','Y17S','Y18','Y53S','Y55','Y27','V21','Y16','Y17','Y35','Y22S'];
const LDU_TYPES=['Fijo','Ruta','Supervisor','Training','GTM','Almacén'];
const LDU_USES=['Exhibición','Promotor','Red de Trabajo','Equipo en Mano','Custodia'];
const LDU_STATES=['Activo','Almacén','Dañado','En Reparación','Perdido','Baja','Pendiente Devolución','Devuelto'];
const LDU_NAV=[['Principal',[['dashboard','🏠','Dashboard']]],['Módulos',[['inventory','📱','Inventario LDU'],['incidents','⚠️','Incidencias'],['stock','📦','Stock'],['modelA','🟦','Modelos Ant. A'],['modelB','🟧','Modelos Ant. B']]],['Herramientas',[['search','🔍','Buscador'],['history','📋','Historial IMEI'],['notifications','🔔','Notificaciones'],['delete','🗑️','Eliminar'],['import','📥','Importar'],['stale','⏱️','IMEIs sin Actualizar'],['users','👥','Usuarios'],['settings','⚙️','Configuración']]]];
const LDU_COLS=[['imei','IMEI'],['marca','Marca'],['modelo','Modelo'],['n_linea','N° Línea'],['responsable','Responsable'],['dni','DNI'],['cargo','Cargo'],['tipo','Tipo'],['supervisor','Supervisor'],['zona','Zona'],['cuenta','Cuenta'],['departamento','Departamento'],['city','City'],['canal','Canal'],['tienda','Tienda'],['tipo_uso','Tipo Uso'],['fecha_asignacion','F. Asignación'],['monto','Monto S/'],['estado','Estado']];
const state={view:'dashboard',devices:[],incidents:[],stock:[],rows:[],filters:{}};
const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/\s+/g,' ').trim();
const groupFor=m=>LDU_GROUP_A.includes(norm(m))?'A':LDU_GROUP_B.includes(norm(m))?'B':'INVENTARIO';
const importAliases={imei:['imei','imei original','imei_original','mei original','mei'],marca:['marca'],modelo:['modelo'],n_linea:['n linea','n° linea','n linea/imei nuevo','n_l/imei nuevo','nlinea','n_linea'],monto:['monto','monto s/','valor s/','valor'],estado:['estado'],responsable:['responsable','nombre completo','nombre'],dni:['dni'],cargo:['cargo'],tipo:['tipo'],supervisor:['supervisor'],zona:['zona'],cuenta:['cuenta'],departamento:['departamento','region'],city:['city','ciudad'],canal:['canal'],tienda:['tienda'],tipo_uso:['tipo uso','tipo de uso','tipouso'],fecha_asignacion:['f asignacion','f. asignacion','fecha asignacion','fecha de asignacion','fecha_asignacio'],fecha_ingreso:['fecha ingreso','fecha de ingreso'],en_inventario:['en inventario','en inventario (si, no, no vivo)'],estado_inventario:['estado inventario'],observaciones:['observaciones'],guia:['guia','guía','n° guia','numero guia'],imei_nuevo:['imei nuevo'],tipo_uso_inc:['tipo uso disp','tipo uso inc'],fecha_incidente:['fecha incidente','fecha del incidente'],doc_autorizacion:['doc autorizacion','doc. autorizacion','documento autorizacion'],modalidad:['modalidad'],estado_proceso:['estado proceso'],documentos_adjuntos:['documentos adjuntos','documentos']};
function canonicalizeImportRows(rows,module){const aliases={};Object.keys(importAliases).forEach(k=>importAliases[k].forEach(a=>aliases[norm(a).replace(/[^A-Z0-9]/g,'')]=k));const incidentAliases={MEIORIGINAL:'imei_original',IMEIORIGINAL:'imei_original',IMEINUEVO:'imei_nuevo',NOMBRE:'nombre_completo',NOMBRECOMPLETO:'nombre_completo',RESPONSABLE:'nombre_completo',FECHADELINCIDENTE:'fecha_incidente',FECHAINCIDENTE:'fecha_incidente',TIPOUSO:'tipo_uso',VALORS:'valor',VALOR:'valor',DOCAUTORIZACION:'doc_autorizacion',MODALIDAD:'modalidad',ESTADOPROCESO:'estado_proceso',DOCUMENTOSADJUNTOS:'documentos_adjuntos',OBSERVACIONES:'observaciones'};const guess=function(clean){if(clean.includes('IMEI')&&clean.includes('NUEVO'))return'imei_nuevo';if(clean.includes('IMEI')||clean==='MEI')return'imei';if(clean.includes('RESPONSABLE')||clean.includes('COLABORADOR')||clean.includes('NOMBRE'))return'responsable';if(clean.includes('TIPOUSO')||clean.includes('USO'))return'tipo_uso';if(clean.includes('FECHA')&&clean.includes('INGRES'))return'fecha_ingreso';if(clean.includes('FECHA')||clean.includes('ASIGN'))return'fecha_asignacion';if(clean.includes('DEPARTAMENTO')||clean.includes('REGION'))return'departamento';if(clean.includes('CIUDAD'))return'city';if(clean.includes('GUIA'))return'guia';if(clean.includes('MONTO')||clean.includes('VALOR')||clean.includes('PRECIO'))return'monto';if(clean.includes('ESTADOPROCESO'))return'estado_proceso';if(clean.includes('ESTADO'))return'estado';return null;};return rows.map(raw=>{const out={};Object.keys(raw||{}).forEach(key=>{const clean=norm(key).replace(/[^A-Z0-9]/g,'');const k=module===1?(incidentAliases[clean]||aliases[clean]||guess(clean)):((aliases[clean]||guess(clean)));if(k)out[k]=raw[key];});if(module===1){if(out.imei_original==null)out.imei_original=out.imei||'';if(out.nombre_completo==null)out.nombre_completo=out.responsable||'';if(out.valor==null)out.valor=out.monto??'';}return out;});}
const safe=v=>esc(v??'—');
function setTitle(title){document.querySelector('#page-title').textContent=title;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));}
function renderNav(){document.querySelector('#main-nav').innerHTML=LDU_NAV.map(([group,items])=>`<div class="nav-group">${group}</div>${items.map(([id,icon,label])=>`<button class="nav-item" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}`).join('');document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>navigate(b.dataset.view));}
function navigate(view){state.view=view;const titles={dashboard:'Dashboard',inventory:'Inventario LDU',incidents:'Incidencias',stock:'Stock',modelA:'Modelos Ant. A',modelB:'Modelos Ant. B',search:'Buscador',history:'Historial IMEI',notifications:'Notificaciones',delete:'Eliminar',import:'Importar',stale:'IMEIs sin Actualizar',users:'Usuarios',settings:'Configuración'};setTitle(titles[view]||'Sistema LDU');const fn={dashboard:renderDashboard,inventory:()=>renderDevices('INVENTARIO'),modelA:()=>renderDevices('A'),modelB:()=>renderDevices('B'),incidents:renderIncidents,stock:renderStock,search:renderSearch,history:renderHistory,notifications:renderNotifications,delete:renderDelete,import:renderImport,stale:renderStale,users:renderUsers,settings:renderSettings}[view];(fn||renderPlaceholder)();}
function loading(text='Cargando...'){document.querySelector('#app').innerHTML=`<div class="loading">⏳ ${text}</div>`;}
function errorView(title,e,retry){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>❌ ${title}</h2></div><div class="error">${safe(e.message||e)}</div><div class="section-body"><button class="btn" onclick="${retry}()">Reintentar</button></div></section>`;}
function card(label,value){return metric(label,value);}
function toolbar(actions){return `<div class="dashboard-toolbar">${actions}</div>`;}
async function loadAll(){const [d,i,s]=await Promise.all([api('listDevices'),api('listIncidents'),api('listStock')]);if(d.status==='error')throw Error(d.message);state.devices=d.data||[];state.incidents=i.data||[];state.stock=s.data||[];document.querySelector('#connection-status').textContent='API conectada';}
function totals(rows){const c=k=>rows.filter(r=>norm(r.estado)===norm(k)).length;const stock=state.stock.length;const enInv=rows.filter(r=>!['Devuelto','Baja'].includes(r.estado)).length;return {stock,enInv,act:c('Activo'),alm:c('Almacén'),dan:c('Dañado'),rep:c('En Reparación'),per:c('Perdido'),baja:c('Baja'),pdev:c('Pendiente Devolución'),dev:c('Devuelto'),falt:Math.max(0,stock-enInv),noInv:state.stock.filter(s=>norm(s.en_inventario)==='NO').length,noVivo:state.stock.filter(s=>norm(s.en_inventario)==='NO VIVO').length,valor:rows.reduce((n,r)=>n+Number(r.monto||r.valor||0),0)};}
function overviewCards(t){return `<div class="cards dashboard-overview">${card('📦 TOTAL STOCK',t.stock)}${card('📋 TOTAL EN INVENTARIO',t.enInv)}${card('✅ TOTAL ACTIVOS',t.act)}${card('🏬 TOTAL EN ALMACÉN',t.alm)}${card('🛠️ TOTAL DAÑADOS',t.dan)}${card('🔧 TOTAL EN REPARACIÓN',t.rep)}${card('🔎 TOTAL PERDIDOS',t.per)}${card('⛔ TOTAL EN BAJA',t.baja)}${card('📦 PENDIENTE DE DEVOLUCIÓN',t.pdev)}${card('↩️ TOTAL DEVUELTOS',t.dev)}${card('⚠️ TOTAL FALTANTE',t.falt)}${card('↩️ TOTAL EQUIPOS DEVUELTOS',t.dev)}${card('🏬 TOTAL EQUIPOS EN ALMACÉN',t.alm)}${card('🚫 TOTAL IMEI NO INVENTARIO',t.noInv)}${card('📦 TOTAL DE STOCK',t.stock)}${card('📵 TOTAL IMEI NO VIVO',t.noVivo)}${card('💰 VALOR TOTAL','S/ '+t.valor.toFixed(2))}</div>`;}
async function renderDashboard(){loading('Cargando Dashboard...');try{await loadAll();const t=totals(state.devices),byType=k=>state.incidents.filter(x=>norm(x.tipo)===norm(k)).length;document.querySelector('#app').innerHTML=toolbar(`<button class="btn" onclick="renderDashboard()">🔄 Actualizar</button><button class="btn secondary" onclick="navigate('import')">📥 Importar Masivo</button><button class="btn secondary" onclick="exportRows(state.devices,'dashboard')">📤 Exportar Excel</button>`)+overviewCards(t)+stateSection('📈 Estados — 📱 Inventario LDU',state.devices.filter(d=>groupFor(d.modelo)==='INVENTARIO'),'INVENTARIO')+stateSection('📈 Estados — 🟦 Modelos Antiguos A',state.devices.filter(d=>groupFor(d.modelo)==='A'),'A')+stateSection('📈 Estados — 🟧 Modelos Antiguos B',state.devices.filter(d=>groupFor(d.modelo)==='B'),'B')+`<section class="section dashboard-incidents"><div class="section-head"><h2>⚠️ Incidencias</h2><button class="btn secondary" onclick="navigate('incidents')">Ver todo →</button></div><div class="cards compact">${card('📊 TOTAL',state.incidents.length)}${card('⏳ PENDIENTE',state.incidents.filter(x=>norm(x.estado_proceso)==='PENDIENTE').length)}${card('🔄 EN CURSO',state.incidents.filter(x=>norm(x.estado_proceso)==='EN CURSO').length)}${card('💥 DAÑADOS',byType('Daño'))}${card('🔍 PERDIDOS',byType('Pérdida'))}${card('🕵️ ROBADOS',byType('Robo'))}${card('📌 OTROS',byType('Otro'))}${card('🔁 REPOSICIÓN',byType('Reposición'))}${card('↩️ DEVOLUCIÓN',byType('Devolución'))}${card('💰 VALOR TOTAL','S/ '+state.incidents.reduce((n,x)=>n+Number(x.valor||0),0).toFixed(2))}</div></section>`+mapSection()+stockSummary()+`<div class="dashboard-bottom"><section class="section"><div class="section-head"><h2>📱 Últimos dispositivos</h2></div>${table(state.devices.slice(-5).reverse(),['imei','modelo','responsable','estado'])}</section><section class="section"><div class="section-head"><h2>⚠️ Incidencias recientes</h2></div>${table(state.incidents.slice(-5).reverse(),['imei_original','tipo','responsable','estado_proceso'])}</section></div>`;}catch(e){errorView('No se pudo cargar Dashboard',e,'renderDashboard');}}
function stateSection(title,rows,group){const t=totals(rows);return `<section class="section dashboard-module ${group.toLowerCase()}"><div class="section-head"><h2>${title}</h2><div><button class="btn secondary" onclick="exportRows(${JSON.stringify(rows).replaceAll('"','&quot;')},'${group}')">📄 Excel</button><button class="btn secondary" onclick="navigate('${group==='A'?'modelA':group==='B'?'modelB':'inventory'}')">Ver todo →</button></div></div><div class="cards compact">${card('📊 Total',rows.length)}${card('✅ Activos',t.act)}${card('🚫 IMEI no inventario',t.noInv)}${card('📵 IMEI no vivo',t.noVivo)}${card('💥 Dañados',t.dan)}${card('🔧 Reparación',t.rep)}${card('🔎 Perdidos',t.per)}${card('⛔ Baja',t.baja)}${card('📦 Pendiente de Devolución',t.pdev)}${card('↩️ Devuelto',t.dev)}${card('💰 Valor total','S/ '+t.valor.toFixed(2))}</div></section>`;}
function mapSection(){const counts={};state.devices.forEach(d=>{const k=d.departamento||'Sin departamento';counts[k]=(counts[k]||0)+1});const accounts=['CLARO','ENTEL','OPEN MARKET','RETAIL','VIVO'];return `<section class="section"><div class="section-head"><h2>📍 Mapeo de LDU por Departamento</h2><div class="map-filters"><select class="select"><option>📍 Departamentos</option></select><select class="select"><option>🏙️ Ciudades</option></select><select class="select"><option>🏢 Cuentas</option></select></div></div><div class="account-cards">${accounts.map(a=>`<article class="account-card account-${a.toLowerCase().replaceAll(' ','-')}"><strong>${a}</strong><b>${state.devices.filter(d=>norm(d.cuenta)===norm(a)).length}</b><span>equipos</span></article>`).join('')}</div><div class="map-content"><div class="peru-map-visual"><div class="peru-outline">🇵🇪</div><strong>Mapa del Perú</strong><small>Se actualizará por departamento al cargar dispositivos.</small></div>${table(Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([departamento,equipos])=>({departamento,equipos})),['departamento','equipos'])}</div></section>`;}
function stockSummary(){const groups=[['✅ Inventario LDU','INVENTARIO'],['🟦 Modelos Antiguos A','A'],['🟧 Modelos Antiguos B','B']];return `<section class="section stock-summary"><div class="section-head"><h2>📦 Resumen de Stock por Modelo</h2><button class="btn secondary" onclick="renderDashboard()">🔄 Actualizar</button></div>${groups.map(([name,g])=>{const rows=state.devices.filter(d=>groupFor(d.modelo)===g);const models=[...new Set(rows.map(x=>x.modelo).filter(Boolean))];return `<div class="stock-group"><div class="stock-group-head"><h3>${name}</h3><div><button class="btn secondary" onclick="navigate('${g==='A'?'modelA':g==='B'?'modelB':'inventory'}')">📋 Ver ${g==='A'?'Mod. A':g==='B'?'Mod. B':'Inventario'}</button><button class="btn secondary" onclick="exportRows(${JSON.stringify(rows).replaceAll('"','&quot;')},'${g}')">📄 Excel</button></div></div>${table(models.map(m=>{const r=rows.filter(x=>x.modelo===m),t=totals(r);return {modelo:m,stock:r.length,en_inv:t.enInv,activos:t.act,almacen:t.alm,danados:t.dan,rep:t.rep,perdidos:t.per,baja:t.baja,pdev:t.pdev,devuelto:t.dev,monto:t.valor.toFixed(2),faltante:Math.max(0,r.length-t.enInv)}}),['modelo','stock','en_inv','activos','almacen','danados','rep','perdidos','baja','pdev','devuelto','monto','faltante'])}</div>`}).join('')}</section>`;}
function renderDevices(group){loading('Cargando inventario...');api('listDevices').then(r=>{if(r.status==='error')throw Error(r.message);const all=r.data||[];const rows=all.filter(d=>groupFor(d.modelo)===group);state.rows=rows;const title=group==='A'?'🟦 Modelos Antiguos A':group==='B'?'🟧 Modelos Antiguos B':'📱 Inventario LDU';document.querySelector('#app').innerHTML=overviewCards(totals(rows))+`<section class="section"><div class="section-head"><h2>${title}</h2><div><button class="btn secondary" onclick="renderDevices('${group}')">🔄 Actualizar</button><button class="btn secondary" onclick="exportRows(window.__filteredRows||[],'${group}')">📄 Excel</button><button class="btn" onclick="openDeviceForm()">＋ Nuevo</button></div></div><div class="section-body"><div class="module-filters"><input id="q" class="input" placeholder="Buscar IMEI, marca, modelo, responsable..."><select id="supervisor" class="select"><option value="">Supervisor</option></select><select id="zona" class="select"><option value="">Zona</option></select><select id="cuenta" class="select"><option value="">Cuenta</option></select><select id="modelo" class="select"><option value="">Modelo</option></select><select id="uso" class="select"><option value="">Tipo de Uso</option></select><select id="estado" class="select"><option value="">Estado</option>${LDU_STATES.map(x=>`<option>${x}</option>`).join('')}</select><button class="btn secondary" id="clear">Limpiar</button></div></div><div class="table-wrap module-table"><table><thead><tr>${LDU_COLS.map(x=>`<th>${x[1]}</th>`).join('')}<th>Acc.</th></tr></thead><tbody id="body"></tbody></table></div></section>`;const keys=['supervisor','zona','cuenta','modelo','tipo_uso'];keys.forEach(k=>{const el=document.querySelector('#'+(k==='tipo_uso'?'uso':k));const vals=[...new Set(rows.map(x=>x[k]).filter(Boolean))];el.innerHTML+=vals.map(v=>`<option>${safe(v)}</option>`).join('')});const draw=()=>{const filters={query:document.querySelector('#q').value.toLowerCase(),supervisor:document.querySelector('#supervisor').value,zona:document.querySelector('#zona').value,cuenta:document.querySelector('#cuenta').value,modelo:document.querySelector('#modelo').value,tipo_uso:document.querySelector('#uso').value,estado:document.querySelector('#estado').value};const out=rows.filter(d=>(!filters.query||Object.values(d).join(' ').toLowerCase().includes(filters.query))&&keys.every(k=>!filters[k]||d[k]===filters[k])&&(!filters.estado||d.estado===filters.estado));window.__filteredRows=out;document.querySelector('#body').innerHTML=out.map(deviceRow).join('')||`<tr><td colspan="20" class="empty">Sin resultados</td></tr>`;document.querySelectorAll('[data-device-action]').forEach(b=>b.onclick=()=>deviceAction(b.dataset.deviceAction,b.dataset.id,out))};['q','supervisor','zona','cuenta','modelo','uso','estado'].forEach(id=>document.querySelector('#'+id).oninput=draw);document.querySelector('#clear').onclick=()=>{['q','supervisor','zona','cuenta','modelo','uso','estado'].forEach(id=>document.querySelector('#'+id).value='');draw()};draw();}).catch(e=>errorView(`No se pudo cargar ${group==='A'?'Modelos Ant. A':group==='B'?'Modelos Ant. B':'Inventario LDU'}`,e,`()=>renderDevices('${group}')`));}
function deviceRow(d){return `<tr>${LDU_COLS.map(([k])=>`<td>${k==='estado'?badge(d[k]):safe(d[k])}</td>`).join('')}<td class="row-actions"><button data-device-action="view" data-id="${safe(d.imei)}">👁️</button><button data-device-action="history" data-id="${safe(d.imei)}">📜</button><button data-device-action="edit" data-id="${safe(d.imei)}">✎️</button><button data-device-action="delete" data-id="${safe(d.imei)}">✕</button></td></tr>`;}
function deviceAction(action,imei,rows){const row=rows.find(x=>String(x.imei)===String(imei));if(action==='view')showDetail(row);if(action==='history'){state.historyImei=imei;navigate('history')}if(action==='edit')openDeviceForm(row);if(action==='delete'){if(confirm('¿Enviar este registro al módulo Eliminar?'))api('deleteDevice',{imei,userId:'web-user'}).then(()=>navigate(state.view));}}
function field(label,name,type='text',value='',extra=''){return `<label><span>${label}</span><input class="input" name="${name}" type="${type}" value="${safe(value).replaceAll('—','')}" ${extra}></label>`;}
function selectField(label,name,values,value=''){return `<label><span>${label}</span><select class="select" name="${name}"><option value="">Seleccionar...</option>${values.map(v=>`<option ${String(v)===String(value)?'selected':''}>${v}</option>`).join('')}</select></label>`;}
async function lookup(form,field){const imei=form.querySelector(`[name="${field}"]`).value;if(!imei)return;try{const r=await api('lookupImei',{imei});if(r.status==='ok'){const d=r.data?.device||r.data?.stock||{};['marca','modelo','n_linea','responsable','dni','cargo','tipo','supervisor','zona','cuenta','departamento','city','canal','tienda','tipo_uso','monto','estado'].forEach(k=>{const e=form.querySelector(`[name="${k}"]`);if(e&&d[k]!=null&&!e.value)e.value=d[k]})}}catch(e){console.warn(e.message)}}
function openDeviceForm(existing={}){const drawer=document.createElement('div');drawer.className='drawer';drawer.innerHTML=`<aside class="drawer-card device-form-card"><div class="section-head"><h2>📱 ${existing.imei?'Editar':'Nuevo'} Dispositivo</h2><button class="btn secondary" id="x">✕</button></div><form class="device-form" id="device-form"><h3>🪪 Identificación</h3><div class="form-grid">${field('IMEI *','imei','text',existing.imei,'required minlength="15" maxlength="17"')}${selectField('Estado','estado',LDU_STATES,existing.estado||'Activo')}${field('Marca','marca','text',existing.marca||'VIVO')}${field('Modelo *','modelo','text',existing.modelo,'required')}${field('N° Línea','n_linea','text',existing.n_linea)}${field('Monto S/','monto','number',existing.monto)}</div><h3>👤 Responsable</h3><div class="form-grid">${field('Nombre completo','responsable','text',existing.responsable)}${field('DNI','dni','text',existing.dni)}${field('Cargo','cargo','text',existing.cargo)}${selectField('Tipo','tipo',LDU_TYPES,existing.tipo)}${field('Supervisor','supervisor','text',existing.supervisor)}</div><h3>📍 Ubicación</h3><div class="form-grid">${field('Zona','zona','text',existing.zona)}${field('Departamento','departamento','text',existing.departamento)}${field('City','city','text',existing.city)}${field('Cuenta','cuenta','text',existing.cuenta)}${field('Canal','canal','text',existing.canal)}${field('Tienda','tienda','text',existing.tienda)}</div><h3>📋 Asignación</h3><div class="form-grid">${selectField('Tipo de Uso','tipo_uso',LDU_USES,existing.tipo_uso)}${field('F. Asignación','fecha_asignacion','date',existing.fecha_asignacion)}<label class="full-field"><span>Observaciones</span><textarea class="input" name="observaciones">${safe(existing.observaciones).replaceAll('—','')}</textarea></label></div><div id="msg"></div><div class="form-actions"><button type="button" class="btn secondary" id="cancel">Cancelar</button><button class="btn" type="submit">💾 Guardar</button></div></form></aside>`;document.body.appendChild(drawer);const form=drawer.querySelector('form'),close=()=>drawer.remove();drawer.querySelector('#x').onclick=close;drawer.querySelector('#cancel').onclick=close;form.querySelector('[name="imei"]').onblur=()=>lookup(form,'imei');form.onsubmit=async e=>{e.preventDefault();const msg=document.querySelector('#msg');msg.textContent='Guardando...';const device=Object.fromEntries(new FormData(form).entries());try{const r=await api(existing.imei?'updateDevice':'createDevice',{device,userId:'web-user'});if(r.status!=='ok')throw Error(r.message);close();navigate(state.view)}catch(err){msg.textContent=err.message}};}
function openIncidentForm(){const drawer=document.createElement('div');drawer.className='drawer';drawer.innerHTML=`<aside class="drawer-card device-form-card"><div class="section-head"><h2>⚠️ Nueva Incidencia</h2><button class="btn secondary" id="x">✕</button></div><form class="device-form" id="incident-form"><h3>⚡ Evento</h3><div class="form-grid">${field('IMEI Original *','imei_original','text','','required minlength="15" maxlength="17"')}${selectField('Tipo','tipo',['Daño','Pérdida','Robo','Otro'])}${field('IMEI Nuevo','imei_nuevo')}${field('Marca','marca')}${field('Modelo','modelo')}${field('N° Línea','n_linea')}${field('Fecha del Incidente','fecha_incidente','date')}${field('Valor S/','valor','number')}${selectField('Tipo Uso','tipo_uso',LDU_USES)}</div><h3>👤 Colaborador</h3><div class="form-grid">${field('Nombre completo','responsable')}${field('DNI','dni')}${field('Cargo','cargo')}${field('Supervisor','supervisor')}</div><h3>⚙️ Proceso</h3><div class="form-grid">${selectField('Modalidad','modalidad',['Sin definir','Pago','Descuento','Reposición','Pendiente'])}${selectField('Estado','estado_proceso',['Pendiente','En Curso','Finalizado','Descontado'])}${selectField('Doc. Autorización','doc_autorizacion',['No','Sí'])}<label class="full-field"><span>Documentos Adjuntos (PDF, XLSX, XLS)</span><input class="input" type="file" id="attachment" accept=".pdf,.xlsx,.xls"></label><label class="full-field"><span>Observaciones</span><textarea class="input" name="observaciones"></textarea></label></div><div id="msg"></div><div class="form-actions"><button type="button" class="btn secondary" id="cancel">Cancelar</button><button class="btn" type="submit">💾 Guardar</button></div></form></aside>`;document.body.appendChild(drawer);const form=drawer.querySelector('form'),close=()=>drawer.remove();drawer.querySelector('#x').onclick=close;drawer.querySelector('#cancel').onclick=close;form.querySelector('[name="imei_original"]').onblur=()=>lookup(form,'imei_original');form.onsubmit=async e=>{e.preventDefault();const msg=form.querySelector('#msg');msg.textContent='Guardando...';try{const incident=Object.fromEntries(new FormData(form).entries());const file=drawer.querySelector('#attachment').files[0];if(file){if(file.size>1500000)throw Error('El archivo adjunto supera 1.5 MB.');incident.attachment={name:file.name,type:file.type,data:await fileToBase64(file)}}const r=await api('createIncident',{incident,userId:'web-user'});if(r.status!=='ok')throw Error(r.message);close();renderIncidents()}catch(err){msg.textContent=err.message}};}
function fileToBase64(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(file)})}
async function renderIncidents(){loading('Cargando incidencias...');try{const r=await api('listIncidents');if(r.status==='error')throw Error(r.message);state.incidents=r.data||[];const c=k=>state.incidents.filter(x=>norm(x.tipo)===norm(k)).length;document.querySelector('#app').innerHTML=overviewCards(totals(state.devices))+`<section class="section"><div class="section-head"><h2>⚠️ Incidencias</h2><div><button class="btn secondary" onclick="renderIncidents()">🔄 Actualizar</button><button class="btn" onclick="openIncidentForm()">＋ Nueva</button></div></div><div class="cards compact">${card('📊 TOTAL',state.incidents.length)}${card('⏳ PENDIENTE',state.incidents.filter(x=>norm(x.estado_proceso)==='PENDIENTE').length)}${card('🔄 EN CURSO',state.incidents.filter(x=>norm(x.estado_proceso)==='EN CURSO').length)}${card('💥 DAÑADOS',c('Daño'))}${card('🔍 PERDIDOS',c('Pérdida'))}${card('🕵️ ROBADOS',c('Robo'))}${card('📌 OTROS',c('Otro'))}${card('🔁 REPOSICIÓN',c('Reposición'))}${card('↩️ DEVOLUCIÓN',c('Devolución'))}${card('💰 VALOR TOTAL','S/ '+state.incidents.reduce((n,x)=>n+Number(x.valor||0),0).toFixed(2))}</div>${table(state.incidents,['imei_original','tipo','imei_nuevo','marca','modelo','responsable','supervisor','fecha_incidente','valor','estado_proceso'])}</div></section>`;}catch(e){errorView('No se pudo cargar Incidencias',e,'renderIncidents')}}
async function renderStock(){loading('Cargando Stock...');try{const r=await api('listStock');if(r.status==='error')throw Error(r.message);state.stock=r.data||[];document.querySelector('#app').innerHTML=`<section class="section stock-screen"><div class="section-head"><h2>📦 Stock</h2><button class="btn secondary" onclick="renderStock()">🔄 Actualizar</button><button class="btn secondary" onclick="exportRows(state.stock,'stock')">📄 Excel</button></div><div class="stock-tabs"><button class="btn active">📦 Stock Vivo</button><button class="btn secondary">🟦 Stock Mod. A</button><button class="btn secondary">🟧 Stock Mod. B</button></div><div class="section-body"><div class="toolbar"><input class="input" id="stock-q" placeholder="Buscar IMEI, cuenta, marca, modelo..."><select class="select" id="stock-cuenta"><option value="">Cuenta</option></select><select class="select" id="stock-marca"><option value="">Marca</option></select><select class="select" id="stock-modelo"><option value="">Modelo</option></select><select class="select" id="stock-inv"><option value="">En Inventario</option><option>SI</option><option>NO</option><option>NO VIVO</option></select><select class="select" id="stock-state"><option value="">Estado Inventario</option>${LDU_STATES.map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="stock-layout"><section class="section stock-panel"><div class="table-wrap module-table"><table><thead><tr><th>Cuenta</th><th>IMEI</th><th>Marca</th><th>Modelo</th><th>Monto S/</th><th>Fecha de ingreso</th><th>En Inventario</th><th>Estado Inventario</th><th>Observaciones</th><th>Acc.</th></tr></thead><tbody id="stock-body"></tbody></table></div></section><section class="section stock-panel"><div class="section-head"><h2>📋 Panel del Equipo</h2></div><div id="stock-detail" class="empty">Selecciona un IMEI para ver sus movimientos.</div></section></div></section>`;const draw=()=>{const q=document.querySelector('#stock-q').value.toLowerCase(),out=state.stock.filter(x=>(!q||Object.values(x).join(' ').toLowerCase().includes(q))&&['cuenta','marca','modelo','en_inventario','estado_inventario'].every(k=>{const id=k==='en_inventario'?'stock-inv':k==='estado_inventario'?'stock-state':'stock-'+k;return !document.querySelector('#'+id).value||norm(x[k])===norm(document.querySelector('#'+id).value)}));document.querySelector('#stock-body').innerHTML=out.map(x=>`<tr><td>${safe(x.cuenta)}</td><td><button class="link-button" data-stock-imei="${safe(x.imei)}">${safe(x.imei)}</button></td><td>${safe(x.marca)}</td><td>${safe(x.modelo)}</td><td>S/ ${safe(x.monto)}</td><td>${safe(x.fecha_ingreso)}</td><td>${safe(x.en_inventario)}</td><td>${badge(x.estado_inventario)}</td><td>${safe(x.observaciones)}</td><td>👁️ 📜 ✎️ ✕</td></tr>`).join('')||'<tr><td colspan="10" class="empty">Sin resultados</td></tr>';document.querySelectorAll('[data-stock-imei]').forEach(b=>b.onclick=()=>{const x=state.stock.find(s=>String(s.imei)===String(b.dataset.stockImei));document.querySelector('#stock-detail').innerHTML=Object.entries(x||{}).map(([k,v])=>`<div class="detail-row"><b>${safe(k)}</b>${safe(v)}</div>`).join('')})};['stock-q','stock-cuenta','stock-marca','stock-modelo','stock-inv','stock-state'].forEach(id=>document.querySelector('#'+id).oninput=draw);['cuenta','marca','modelo'].forEach(k=>{const id='stock-'+k;document.querySelector('#'+id).innerHTML+= [...new Set(state.stock.map(x=>x[k]).filter(Boolean))].map(v=>`<option>${safe(v)}</option>`).join('')});draw();}catch(e){errorView('No se pudo cargar Stock',e,'renderStock')}}
function table(rows,fields){return `<div class="table-wrap"><table><thead><tr>${fields.map(f=>`<th>${safe(f.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${fields.map(f=>`<td>${f.includes('estado')?badge(r[f]):safe(r[f])}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${fields.length}" class="empty">Sin datos</td></tr>`}</tbody></table></div>`;}
function renderSearch(){loading('Buscador...');Promise.all([api('listDevices'),api('listStock'),api('listIncidents')]).then(([d,s,i])=>{const rows=[...(d.data||[]).map(x=>({...x,modulo:'Inventario'})),...(s.data||[]).map(x=>({...x,modulo:'Stock'})),...(i.data||[]).map(x=>({...x,modulo:'Incidencia',imei:x.imei_original}))];document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>🔍 Buscador General</h2><button class="btn secondary" onclick="renderSearch()">🔄 Actualizar</button><button class="btn secondary" onclick="exportRows(window.__searchRows||[],'buscador')">📄 Excel</button></div><div class="section-body"><input id="search-q" class="input" placeholder="IMEI, nombre, modelo, DNI, supervisor..."></div><div id="search-results"></div></section>`;window.__searchRows=rows;const draw=()=>{const q=document.querySelector('#search-q').value.toLowerCase(),out=rows.filter(x=>!q||Object.values(x).join(' ').toLowerCase().includes(q));document.querySelector('#search-results').innerHTML=table(out,['modulo','imei','marca','modelo','responsable','dni','supervisor','zona','cuenta','estado'])};document.querySelector('#search-q').oninput=draw;draw()}).catch(e=>errorView('No se pudo cargar Buscador',e,'renderSearch'));}
async function renderHistory(){loading('Historial IMEI...');try{const r=await api('listHistory');if(r.status==='error')throw Error(r.message);const rows=r.data||[];document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>📋 Historial IMEI</h2><button class="btn secondary" onclick="renderHistory()">🔄 Actualizar</button><button class="btn secondary" onclick="exportRows(window.__historyRows||[],'historial')">📄 Excel</button></div><div class="section-body"><input id="history-q" class="input" placeholder="IMEI completo o parcial..." value="${safe(state.historyImei||'')}"></div><div id="history-results"></div></section>`;window.__historyRows=rows;const draw=()=>{const q=document.querySelector('#history-q').value.toLowerCase(),out=rows.filter(x=>!q||Object.values(x).join(' ').toLowerCase().includes(q));document.querySelector('#history-results').innerHTML=table(out,['timestamp','action','user_id','imei','module','justification','after_json'])};document.querySelector('#history-q').oninput=draw;draw();}catch(e){errorView('No se pudo cargar Historial IMEI',e,'renderHistory')}}
function renderNotifications(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>🔔 Notificaciones</h2><button class="btn secondary" onclick="renderNotifications()">🔄 Actualizar</button></div><div class="section-body"><p>Selecciona dispositivos y envía una notificación a supervisores.</p><form id="notification-form" class="device-form"><div class="form-grid">${field('Destinatario','recipient','email','','required')}${field('CC','cc')}${field('Asunto','subject','text','Incidencia registrada')}<label class="full-field"><span>Mensaje</span><textarea class="input" name="message" required></textarea></label></div><button class="btn" type="submit">📨 Enviar correo</button><div id="notification-msg"></div></form></div></section><section class="section"><div class="section-head"><h2>📋 Historial de Notificaciones</h2></div><div id="notification-history" class="empty">Cargando...</div></section>`;api('listNotifications').then(r=>{document.querySelector('#notification-history').innerHTML=table(r.data||[],['timestamp','type','recipient','subject','status'])});document.querySelector('#notification-form').onsubmit=async e=>{e.preventDefault();const msg=document.querySelector('#notification-msg');const notification=Object.fromEntries(new FormData(e.target).entries());msg.textContent='Enviando...';const r=await api('sendNotification',{notification,userId:'web-user'});msg.textContent=r.status==='ok'?'Notificación registrada.':r.message;};}
function renderDelete(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>🗑️ Eliminar Registros</h2><button class="btn secondary" onclick="renderDelete()">🔄 Actualizar</button><span>La eliminación queda registrada en Historial IMEI.</span></div><div class="section-body"><input id="delete-imei" class="input" placeholder="IMEI a eliminar"><button class="btn" id="delete-btn">🗑️ Enviar a eliminados</button><div id="delete-msg"></div></div></section><section class="section"><div class="section-head"><h2>📋 Registros eliminados</h2></div><div id="deleted-results" class="empty">Cargando...</div></section>`;api('listDeleted').then(r=>document.querySelector('#deleted-results').innerHTML=table(r.data||[],['deleted_at','deleted_by','imei','module','reason']));document.querySelector('#delete-btn').onclick=async()=>{const imei=document.querySelector('#delete-imei').value,msg=document.querySelector('#delete-msg');msg.textContent='Procesando...';const r=await api('deleteDevice',{imei,userId:'web-user'});msg.textContent=r.status==='ok'?'Registro eliminado y auditado.':r.message;};}
function renderUsers(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>👥 Usuarios</h2><button class="btn secondary" onclick="renderUsers()">🔄 Actualizar</button><button class="btn" onclick="openUserForm()">＋ Nuevo</button></div><div id="users-results" class="empty">Cargando...</div></section>`;api('listUsers').then(r=>document.querySelector('#users-results').innerHTML=table(r.data||[],['user_id','username','name','role','email','active']));}
function openUserForm(){const u=prompt('Usuario, nombre, correo y rol separados por coma (ej. logistica,Logística,correo@empresa.com,Consulta)');if(!u)return;const [username,name,email,role]=u.split(',').map(x=>x.trim());api('createUser',{user:{username,name,email,role:role||'Consulta',active:true},userId:'admin'}).then(r=>{if(r.status!=='ok')alert(r.message);else renderUsers()});}
function renderSettings(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>⚙️ Configuración</h2><button class="btn secondary" onclick="renderSettings()">🔄 Actualizar</button></div><div class="section-body"><p>Herramientas de mantenimiento y sincronización general.</p><div class="toolbar"><button class="btn" onclick="api('setup').then(r=>alert(r.message||'Hojas listas'))">🧱 Inicializar hojas</button><button class="btn secondary" onclick="api('health').then(r=>alert(JSON.stringify(r)))">🔌 Probar conexión</button><button class="btn secondary" onclick="api('setup').then(()=>alert('Estructura validada'))">✅ Validar estructura</button></div></div></section>`;}
function renderImport(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>📥 Importar Masivo</h2><button class="btn secondary" onclick="renderImport()">🔄 Actualizar</button><span>CSV, XLSX o XLS · detecta columnas y revisa antes de importar.</span></div><div class="import-grid">${['Inventario LDU','Incidencias','Stock Vivo','Stock Mod. A','Stock Mod. B'].map((x,i)=>`<article class="import-card"><h3>${x}</h3><input type="file" accept=".csv,.xlsx,.xls" data-file="${i}"><button class="btn" data-preview="${i}" disabled>👁️ Revisar vista previa</button><div class="import-message" data-message="${i}"></div></article>`).join('')}</div></section>`;document.querySelectorAll('[data-file]').forEach(input=>input.onchange=()=>{const b=input.closest('.import-card').querySelector('[data-preview]');b.disabled=!input.files.length;b.onclick=()=>previewImport(input.files[0],Number(input.dataset.file),input.closest('.import-card'))});}
async function previewImport(file,module,card){const msg=card.querySelector('[data-message]');try{const book=XLSX.read(await file.arrayBuffer(),{type:'array'}),rawRows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:''}),rows=canonicalizeImportRows(rawRows,module);if(!rows.length)throw Error('El archivo no contiene registros.');const drawer=document.createElement('div');drawer.className='drawer';const cols=Object.keys(rows[0]);drawer.innerHTML=`<aside class="drawer-card import-preview-card"><div class="section-head"><h2>📋 Vista previa — ${safe(file.name)}</h2><button class="btn secondary" id="close">✕</button></div><p>Registros detectados: <strong>${rows.length}</strong></p>${table(rows.slice(0,10),cols)}<div id="import-result"></div><div class="form-actions"><button class="btn secondary" id="cancel">Cancelar</button><button class="btn" id="confirm">📥 Importar masivo</button></div></aside>`;document.body.appendChild(drawer);const close=()=>drawer.remove();drawer.querySelector('#close').onclick=close;drawer.querySelector('#cancel').onclick=close;drawer.querySelector('#confirm').onclick=async()=>{const out=drawer.querySelector('#import-result'),button=drawer.querySelector('#confirm');button.disabled=true;let imported=0,updated=0,rejected=0;out.textContent='Importando por lotes...';for(let start=0;start<rows.length;start+=25){const batch=rows.slice(start,start+25);const r=await api('importRows',{module,rows:batch,userId:'importacion'});if(r.status==='ok'){imported+=r.data?.imported||batch.length;updated+=r.data?.updated||0}else rejected+=batch.length}out.textContent=`Importados: ${imported}. Actualizados: ${updated}. Rechazados: ${rejected}.`;button.disabled=false;if(!rejected){setTimeout(()=>{close();navigate(module===1?'incidents':module>=2?'stock':'inventory')},500)}};}catch(e){msg.textContent='Error: '+e.message}}
function renderStale(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>⏱️ IMEIs sin Actualizar</h2><button class="btn secondary" onclick="renderStale()">🔄 Actualizar</button></div><div class="empty">Se mostrará aquí el control de IMEIs que no hayan cambiado.</div></section>`;}
function renderPlaceholder(){document.querySelector('#app').innerHTML='<section class="section"><div class="empty">Módulo preparado.</div></section>';}
function exportRows(rows,name){const data=rows||[];if(window.XLSX){const ws=XLSX.utils.json_to_sheet(data);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Datos');XLSX.writeFile(wb,`LDU_${name}.xlsx`)}else alert('No se pudo cargar el exportador Excel.')}
function showDetail(row){const drawer=document.createElement('div');drawer.className='drawer';drawer.innerHTML=`<aside class="drawer-card"><div class="section-head"><h2>Detalle</h2><button class="btn secondary" id="x">✕</button></div>${Object.entries(row||{}).map(([k,v])=>`<div class="detail-row"><b>${safe(k)}</b>${safe(v)}</div>`).join('')}</aside>`;document.body.appendChild(drawer);drawer.querySelector('#x').onclick=()=>drawer.remove();}
document.addEventListener('DOMContentLoaded',()=>{renderNav();navigate('dashboard')});

// V11: reglas compartidas para presentación y navegación.
function money(value){const n=Number(String(value??0).replace(/[^0-9.-]/g,''));return `S/ ${Number.isFinite(n)?n.toFixed(2):'0.00'}`;}
const MONEY_KEYS=new Set(['monto','valor','monto s/','valor s/','monto_s/']);
const displayCell=(field,value)=>MONEY_KEYS.has(String(field).toLowerCase())?money(value):displayImportValue(value,field);
let tableInstance=0;
function table(rows,fields){const id=`ldu-table-${++tableInstance}`,pageSize=20;window.__tablePages=window.__tablePages||{};window.__tablePages[id]={rows,fields,page:1,pageSize};setTimeout(()=>drawPagedTable(id),0);return `<div class="table-wrap"><table id="${id}"><thead><tr>${fields.map(f=>`<th>${safe(f.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody></tbody></table><div class="pagination" id="${id}-pager"></div></div>`}
function drawPagedTable(id){const t=window.__tablePages?.[id],el=document.getElementById(id);if(!t||!el)return;const total=t.rows.length,pages=Math.max(1,Math.ceil(total/t.pageSize));t.page=Math.min(t.page,pages);const start=(t.page-1)*t.pageSize;el.querySelector('tbody').innerHTML=(t.rows.slice(start,start+t.pageSize).map(r=>`<tr>${t.fields.map(f=>`<td>${String(f).toLowerCase().includes('estado')?badge(displayCell(f,r[f])):safe(displayCell(f,r[f]))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${t.fields.length}" class="empty">Sin datos</td></tr>`);const p=document.getElementById(`${id}-pager`);p.innerHTML=`<span>Mostrando ${total?start+1:0}–${Math.min(start+t.pageSize,total)} de ${total}</span><button class="btn secondary" ${t.page<=1?'disabled':''} data-page="prev">‹</button><span>Página ${t.page} de ${pages}</span><button class="btn secondary" ${t.page>=pages?'disabled':''} data-page="next">›</button>`;p.querySelector('[data-page="prev"]')?.addEventListener('click',()=>{t.page--;drawPagedTable(id)});p.querySelector('[data-page="next"]')?.addEventListener('click',()=>{t.page++;drawPagedTable(id)})}
function mapSection(){const source=state.devices||[],departments=[...new Set(source.map(d=>d.departamento).filter(Boolean))].sort(),cities=[...new Set(source.map(d=>d.city).filter(Boolean))].sort(),accounts=[...new Set(source.map(d=>d.cuenta).filter(Boolean))].sort();const options=(values,placeholder)=>`<option value="">${placeholder}</option>${values.map(v=>`<option value="${safe(v)}">${safe(v)}</option>`).join('')}`;const rows=source.map((d,i)=>({...d,_x:12+(i*17)%76,_y:18+(i*29)%68}));return `<section class="section"><div class="section-head"><h2>📍 Mapeo de LDU por Departamento</h2><div class="map-filters"><select id="map-department" class="select">${options(departments,'📍 Departamento')}</select><select id="map-city" class="select">${options(cities,'🏙️ Ciudad')}</select><select id="map-account" class="select">${options(accounts,'🏢 Cuenta')}</select></div></div><div class="map-content"><div><div class="map-canvas" id="ldu-map"><div class="peru-outline">🇵🇪</div></div><div class="map-legend" id="map-legend">Selecciona filtros para actualizar el mapa.</div></div><div id="map-table"></div></div></section>`}
function drawMap(){const source=state.devices||[],filter=(id,key)=>document.getElementById(id)?.value;const dep=filter('map-department'),city=filter('map-city'),account=filter('map-account');const out=source.filter(d=>(!dep||norm(d.departamento)===norm(dep))&&(!city||norm(d.city)===norm(city))&&(!account||norm(d.cuenta)===norm(account)));const map=document.getElementById('ldu-map'),legend=document.getElementById('map-legend'),tableHost=document.getElementById('map-table');if(!map)return;map.querySelectorAll('.map-marker').forEach(x=>x.remove());out.forEach((d,i)=>{const marker=document.createElement('button');marker.className='map-marker';marker.style.left=`${12+(i*17)%76}%`;marker.style.top=`${18+(i*29)%68}%`;marker.title=`${d.city||d.departamento||'Sin ubicación'} · ${d.imei||''}`;marker.textContent='📱';map.appendChild(marker)});legend.textContent=`${out.length} LDU · ${[...new Set(out.map(d=>d.city||d.departamento).filter(Boolean))].join(', ')||'Sin ubicación registrada'}`;const counts={};out.forEach(d=>{const key=d.city||d.departamento||'Sin ubicación';counts[key]=(counts[key]||0)+1});tableHost.innerHTML=table(Object.entries(counts).map(([ubicacion,cantidad])=>({ubicacion,cantidad})),['ubicacion','cantidad'])}
const _renderDashboard=renderDashboard;renderDashboard=async function(){await _renderDashboard();document.querySelectorAll('#map-department,#map-city,#map-account').forEach(el=>el.addEventListener('change',drawMap));drawMap()};
const _openIncidentForm=openIncidentForm;openIncidentForm=function(){_openIncidentForm();const form=document.querySelector('#incident-form');if(!form)return;const group=form.querySelector('h3')?.nextElementSibling;if(group&&!form.querySelector('[name="zona"]'))group.insertAdjacentHTML('beforeend',field('Zona','zona'));};
function deviceRow(d){return `<tr>${LDU_COLS.map(([k])=>`<td>${k==='estado'?badge(d[k]):k==='monto'?safe(money(d[k])):safe(displayImportValue(d[k],k))}</td>`).join('')}<td class="row-actions"><button data-device-action="view" data-id="${safe(d.imei)}">👁️</button><button data-device-action="history" data-id="${safe(d.imei)}">📜</button><button data-device-action="edit" data-id="${safe(d.imei)}">✎️</button><button data-device-action="delete" data-id="${safe(d.imei)}">✕</button></td></tr>`}
function stockSummary(){const groups=[['✅ Inventario LDU','INVENTARIO'],['🟦 Modelos Antiguos A','A'],['🟧 Modelos Antiguos B','B']];return `<section class="section stock-summary"><div class="section-head"><h2>📦 Resumen de Stock por Modelo</h2><button class="btn secondary" onclick="renderDashboard()">🔄 Actualizar</button></div>${groups.map(([name,g])=>{const rows=state.devices.filter(d=>groupFor(d.modelo)===g),models=[...new Set(rows.map(x=>x.modelo).filter(Boolean))],items=models.map(m=>{const r=rows.filter(x=>x.modelo===m),t=totals(r);return {modelo:m,stock:r.length,en_inv:t.enInv,activos:t.act,almacen:t.alm,danados:t.dan,rep:t.rep,perdidos:t.per,baja:t.baja,pdev:t.pdev,devuelto:t.dev,monto:t.valor,faltante:Math.max(0,r.length-t.enInv)}});const t=totals(rows);items.push({modelo:'TOTAL',stock:rows.length,en_inv:t.enInv,activos:t.act,almacen:t.alm,danados:t.dan,rep:t.rep,perdidos:t.per,baja:t.baja,pdev:t.pdev,devuelto:t.dev,monto:t.valor,faltante:Math.max(0,rows.length-t.enInv)});return `<div class="stock-group"><div class="stock-group-head"><h3>${name}</h3><button class="btn secondary" onclick="navigate('${g==='A'?'modelA':g==='B'?'modelB':'inventory'}')">📋 Ver módulo</button></div>${table(items,['modelo','stock','en_inv','activos','almacen','danados','rep','perdidos','baja','pdev','devuelto','monto','faltante'])}</div>`}).join('')}</section>`}

// V12: módulos funcionales solicitados en la especificación.
const LDU_SEARCH_COLS=['modulo','imei','marca','modelo','n_linea','responsable','dni','cargo','tipo','supervisor','zona','cuenta','departamento','city','canal','tienda','tipo_uso','fecha_asignacion','monto','estado','observaciones'];
async function loadUnified(){const [d,s,i]=await Promise.all([api('listDevices'),api('listStock'),api('listIncidents')]);const devices=(d.data||[]).map(x=>({...x,modulo:'Inventario'}));const stock=(s.data||[]).map(x=>({...x,modulo:'Stock'}));const incidents=(i.data||[]).map(x=>({...x,modulo:'Incidencias',imei:x.imei||x.imei_original,n_linea:x.n_linea||x.imei_nuevo,responsable:x.responsable||x.nombre,monto:x.monto??x.valor,fecha_asignacion:x.fecha_asignacion||x.fecha_incidente}));return [...devices,...stock,...incidents]}
function renderUnifiedRows(rows){return rows.map(x=>{const out={};LDU_SEARCH_COLS.forEach(k=>out[k]=x[k]??'');return out})}
async function renderSearch(){loading('Cargando buscador...');try{const rows=renderUnifiedRows(await loadUnified());window.__searchRows=rows;document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>🔍 Buscador Global</h2><button class="btn secondary" onclick="renderSearch()">🔄 Actualizar</button></div><div class="section-body"><input id="search-q" class="input" placeholder="Busca por IMEI, responsable, supervisor, modelo o DNI..."><select id="search-module" class="select"><option value="">Todos los módulos</option><option>Inventario</option><option>Stock</option><option>Incidencias</option></select></div><div id="search-results"></div></section>`;const draw=()=>{const q=norm(document.querySelector('#search-q').value),m=document.querySelector('#search-module').value;const out=rows.filter(x=>(!q||Object.values(x).some(v=>norm(v).includes(q)))&&(!m||x.modulo===m));window.__searchRows=out;document.querySelector('#search-results').innerHTML=table(out,LDU_SEARCH_COLS)};['search-q','search-module'].forEach(id=>document.querySelector('#'+id).addEventListener('input',draw));draw()}catch(e){errorView('No se pudo cargar Buscador',e,'renderSearch')}}
const LDU_HISTORY_COLS=['timestamp','action','user_id','imei','marca','modelo','n_linea','responsable','dni','cargo','tipo','supervisor','zona','cuenta','departamento','city','canal','tienda','tipo_uso','fecha_asignacion','monto','estado','observaciones'];
async function renderHistory(){loading('Cargando historial...');try{const r=await api('listHistory');if(r.status==='error')throw Error(r.message);const rows=(r.data||[]).map(x=>{let after={};try{after=typeof x.after_json==='string'?JSON.parse(x.after_json):x.after_json||{}}catch{};return {...after,...x,fecha_asignacion:x.fecha_asignacion||after.fecha_asignacion,monto:x.monto??after.monto,observaciones:x.observaciones||after.observaciones}});document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>📋 Historial IMEI</h2><button class="btn secondary" onclick="renderHistory()">🔄 Actualizar</button></div><div class="section-body"><input id="history-q" class="input" placeholder="IMEI completo o parcial..."></div><div id="history-results"></div></section>`;const draw=()=>{const q=norm(document.querySelector('#history-q').value),out=rows.filter(x=>!q||norm(x.imei).includes(q));window.__historyRows=out;document.querySelector('#history-results').innerHTML=table(out,LDU_HISTORY_COLS)};document.querySelector('#history-q').oninput=draw;draw()}catch(e){errorView('No se pudo cargar Historial IMEI',e,'renderHistory')}}
async function renderIncidents(){loading('Cargando incidencias...');try{const r=await api('listIncidents');if(r.status==='error')throw Error(r.message);state.incidents=r.data||[];const cols=['imei_original','tipo','imei_nuevo','nombre','dni','cargo','zona','supervisor','modelo','fecha_incidente','tipo_uso','valor','doc_autorizacion','modalidad','estado_proceso','documentos_adjuntos','acciones'];const rows=state.incidents.map(x=>({...x,nombre:x.nombre||x.responsable,valor:x.valor??x.monto,acciones:'👁️  ✎️  📋  📄  ✕'}));document.querySelector('#app').innerHTML=`<section class="section incidents-screen"><div class="section-head"><h2>⚠️ Incidencias</h2><div><button class="btn secondary" onclick="renderIncidents()">🔄 Actualizar</button><button class="btn" onclick="openIncidentForm()">＋ Nueva Incidencia</button></div></div>${table(rows,cols)}</section>`}catch(e){errorView('No se pudo cargar Incidencias',e,'renderIncidents')}}
async function renderNotifications(){loading('Cargando notificaciones...');try{const devices=renderUnifiedRows(await loadUnified()),r=await api('listNotifications');document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>🔔 Notificaciones</h2></div><form id="notification-form" class="device-form"><h3>📱 Seleccionar dispositivo(s)</h3><input id="notification-device-q" class="input" placeholder="Busca por IMEI, Responsable, Supervisor, Modelo..."><div id="notification-devices" class="selection-list"></div><h3>📤 Redactar y enviar</h3><div class="form-grid">${selectField('Tipo de notificación','type',['⚠️ Incidencia registrada','📦 Cambio de stock','📋 Cambio de responsable'])}${field('Asunto','subject','text','Notificación LDU','required')}<label class="full-field"><span>Destinatarios (1 a 4 correos, separados por coma) *</span><input class="input" name="recipient" type="text" placeholder="correo1@dominio.com, correo2@dominio.com" required></label>${field('CC','cc','text','')}<label class="full-field"><span>Mensaje</span><textarea class="input" name="message" required></textarea></label></div><p class="form-note">Los correos se envían únicamente a los correos ingresados manualmente en este formulario. La cuenta de Gmail es utilizada como remitente.</p><div id="notification-msg"></div><button class="btn" type="submit">📤 Enviar correo</button><button class="btn secondary" type="reset">🗑️ Limpiar</button></form></section><section class="section"><div class="section-head"><h2>📋 Historial de Notificaciones Enviadas</h2></div>${table(r.data||[],['timestamp','type','subject','recipient','zona','role','email','cc','sender','status'])}</section>`;const drawDevices=()=>{const q=norm(document.querySelector('#notification-device-q').value);document.querySelector('#notification-devices').innerHTML=devices.filter(x=>!q||Object.values(x).some(v=>norm(v).includes(q))).slice(0,20).map((x,i)=>`<label class="selection-row"><input type="checkbox" name="selected_imei" value="${safe(x.imei)}"> <b>${safe(x.imei)}</b> · ${safe(x.responsable||x.modelo)} · ${safe(x.modulo)}</label>`).join('')||'<div class="empty">Sin coincidencias</div>'};document.querySelector('#notification-device-q').oninput=drawDevices;drawDevices();document.querySelector('#notification-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),recipients=String(f.get('recipient')||'').split(',').map(x=>x.trim()).filter(Boolean);if(recipients.length<1||recipients.length>4)return alert('Ingresa entre 1 y 4 destinatarios.');const selected=[...document.querySelectorAll('[name="selected_imei"]:checked')].map(x=>x.value);const msg=document.querySelector('#notification-msg');msg.textContent='Enviando...';const out=await api('sendNotification',{notification:{type:f.get('type'),subject:f.get('subject'),recipient:recipients.join(','),cc:f.get('cc'),message:f.get('message'),imeis:selected},userId:'web-user'});msg.textContent=out.status==='ok'?'Notificación enviada y registrada.':(out.message||'No se pudo enviar.')}}catch(e){errorView('No se pudo cargar Notificaciones',e,'renderNotifications')}}
async function renderDelete(){loading('Cargando eliminados...');try{const rows=renderUnifiedRows(await loadUnified()),r=await api('listDeleted');document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>🗑️ Eliminar</h2></div><div class="toolbar"><input id="delete-q" class="input" placeholder="🔍 Buscar IMEI, supervisor, zona, modelo..."><select id="delete-state" class="select"><option value="">Estado</option>${LDU_STATES.map(x=>`<option>${x}</option>`).join('')}</select><input id="delete-reason" class="input" placeholder="Justificación de eliminación (obligatoria)"><button class="btn" id="delete-selected">🗑️ Eliminar seleccionados</button></div><div id="delete-results"></div></section><section class="section"><h2>📋 Historial de eliminaciones</h2>${table(r.data||[],['deleted_at','deleted_by','imei','module','reason'])}</section>`;const draw=()=>{const q=norm(document.querySelector('#delete-q').value),st=norm(document.querySelector('#delete-state').value),out=rows.filter(x=>(!q||Object.values(x).some(v=>norm(v).includes(q)))&&(!st||norm(x.estado)===st));document.querySelector('#delete-results').innerHTML=`<table><thead><tr><th></th>${LDU_SEARCH_COLS.map(x=>`<th>${safe(x)}</th>`).join('')}</tr></thead><tbody>${out.map(x=>`<tr><td><input type="checkbox" data-delete-imei="${safe(x.imei)}"></td>${LDU_SEARCH_COLS.map(k=>`<td>${safe(displayCell(k,x[k]))}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="22">Sin resultados</td></tr>'}</tbody></table>`};document.querySelector('#delete-q').oninput=draw;document.querySelector('#delete-state').oninput=draw;document.querySelector('#delete-selected').onclick=async()=>{const reason=document.querySelector('#delete-reason').value.trim(),imeis=[...document.querySelectorAll('[data-delete-imei]:checked')].map(x=>x.dataset.deleteImei);if(!reason)return alert('La justificación es obligatoria.');if(!imeis.length)return alert('Selecciona al menos un registro.');if(!confirm(`Se eliminarán ${imeis.length} registros. ¿Continuar?`))return;for(const imei of imeis)await api('deleteDevice',{imei,justification:reason,userId:'web-user'});renderDelete()};draw()}catch(e){errorView('No se pudo cargar Eliminar',e,'renderDelete')}}
async function renderUsers(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>👥 Usuarios</h2><button class="btn" onclick="openUserForm()">＋ Nuevo Usuario</button></div><div id="users-results"></div></section>`;const r=await api('listUsers');document.querySelector('#users-results').innerHTML=table(r.data||[],['user_id','username','name','role','email','active','actions'])}
function openUserForm(){const drawer=document.createElement('div');drawer.className='drawer';drawer.innerHTML=`<aside class="drawer-card"><div class="section-head"><h2>👤 Nuevo Usuario</h2><button class="btn secondary" id="close-user">✕</button></div><form id="user-form" class="device-form">${field('Usuario *','username','text','','required')}${field('Nombre completo','name')}${field('Contraseña *','password','password','','required minlength="4"')}${selectField('Rol','role',['Consulta','Operador','Supervisor','Administrador'])}${field('Correo electrónico','email','email')}<div id="user-msg"></div><button class="btn">💾 Guardar usuario</button></form></aside>`;document.body.appendChild(drawer);drawer.querySelector('#close-user').onclick=()=>drawer.remove();drawer.querySelector('form').onsubmit=async e=>{e.preventDefault();const user=Object.fromEntries(new FormData(e.target).entries()),msg=drawer.querySelector('#user-msg'),r=await api('createUser',{user,userId:'admin'});if(r.status!=='ok')msg.textContent=r.message||'No se pudo guardar';else{drawer.remove();renderUsers()}}}
function renderSettings(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>⚙️ Configuración</h2></div><div class="settings-grid"><article class="section"><h3>🔐 Seguridad</h3><form id="password-form" class="device-form">${field('Contraseña actual','current_password','password','','required')}${field('Nueva contraseña','new_password','password','','required minlength="4"')}${field('Confirmar contraseña','confirm_password','password','','required minlength="4"')}<button class="btn">🔐 Cambiar contraseña</button></form></article><article class="section"><h3>🛠️ Mantenimiento</h3><div class="toolbar"><button class="btn" onclick="api('health').then(r=>alert(r.message||'Conexión activa'))">🔌 Probar conexión</button><button class="btn secondary" onclick="api('setup').then(r=>alert(r.message||'Hojas inicializadas'))">📁 Inicializar hojas</button><button class="btn secondary" onclick="api('setup').then(r=>alert('Estructura validada'))">📋 Validar estructura</button></div></article></div></section>`;document.querySelector('#password-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('new_password')!==f.get('confirm_password'))return alert('Las contraseñas no coinciden.');alert('La solicitud de cambio está lista para conectarse con Apps Script.')}}

// Correcciones de estabilidad y experiencia para la versión publicada.
function displayImportValue(value,key){if(value===null||value===undefined||value==='')return '';if(/fecha|date/i.test(String(key))&&typeof value==='number'&&window.XLSX?.SSF){const d=XLSX.SSF.parse_date_code(value);if(d)return `${String(d.d).padStart(2,'0')}/${String(d.m).padStart(2,'0')}/${d.y}`;}if(/fecha|date/i.test(String(key))&&value instanceof Date)return `${String(value.getDate()).padStart(2,'0')}/${String(value.getMonth()+1).padStart(2,'0')}/${value.getFullYear()}`;return value}
function table(rows,fields){return `<div class="table-wrap"><table><thead><tr>${fields.map(f=>`<th>${safe(f.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${fields.map(f=>`<td>${f.includes('estado')?badge(displayImportValue(r[f],f)):safe(displayImportValue(r[f],f))}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${fields.length}" class="empty">Sin datos</td></tr>`}</tbody></table></div>`}
function renderSearch(){document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>🔍 Buscador General</h2><div><button class="btn secondary" onclick="renderSearch()">🔄 Actualizar</button><button class="btn secondary" onclick="exportRows(window.__searchRows||[],'buscador')">📄 Excel</button></div></div><div class="section-body"><input id="search-q" class="input" placeholder="Ingresa un IMEI, nombre, modelo o DNI..."><select id="search-module" class="select"><option value="">Todos los módulos</option><option value="Inventario">Inventario</option><option value="Stock">Stock</option><option value="Incidencia">Incidencias</option></select></div><div id="search-results"><div class="empty">Escribe un término para buscar.</div></div></section>`;const run=async()=>{const q=document.querySelector('#search-q').value.trim();if(!q){window.__searchRows=[];document.querySelector('#search-results').innerHTML='<div class="empty">Escribe un término para buscar.</div>';return}document.querySelector('#search-results').innerHTML='<div class="loading">🔎 Buscando...</div>';try{const [d,s,i]=await Promise.all([api('listDevices',{query:q}),api('listStock',{query:q}),api('listIncidents')]);const mod=document.querySelector('#search-module').value;const rows=[...(d.data||[]).map(x=>({...x,modulo:'Inventario'})),...(s.data||[]).map(x=>({...x,modulo:'Stock'})),...(i.data||[]).filter(x=>Object.values(x).join(' ').toLowerCase().includes(q.toLowerCase())).map(x=>({...x,modulo:'Incidencia',imei:x.imei_original}))].filter(x=>!mod||x.modulo===mod);window.__searchRows=rows;document.querySelector('#search-results').innerHTML=rows.length?table(rows,['modulo','imei','marca','modelo','responsable','dni','supervisor','zona','cuenta','estado']):'<div class="empty">Sin resultados.</div>'}catch(e){errorView('No se pudo cargar Buscador',e,'renderSearch')}};document.querySelector('#search-q').oninput=run;document.querySelector('#search-module').onchange=run}
async function renderHistory(){loading('Historial IMEI...');try{const r=await api('listHistory');if(r.status==='error')throw Error(r.message);const rows=r.data||[];document.querySelector('#app').innerHTML=`<section class="section"><div class="section-head"><h2>📋 Historial IMEI</h2><div><button class="btn secondary" onclick="renderHistory()">🔄 Actualizar</button><button class="btn secondary" onclick="exportRows(window.__historyRows||[],'historial')">📄 Excel</button></div></div><div class="section-body"><input id="history-q" class="input" placeholder="IMEI completo o parcial..." value="${safe(state.historyImei||'')}"></div><div id="history-results"></div></section>`;const draw=()=>{const q=document.querySelector('#history-q').value.trim().toLowerCase();const out=rows.filter(x=>!q||String(x.imei||'').toLowerCase().includes(q));window.__historyRows=out;document.querySelector('#history-results').innerHTML=table(out,['timestamp','action','user_id','imei','module','justification','after_json'])};document.querySelector('#history-q').oninput=draw;draw()}catch(e){errorView('No se pudo cargar Historial IMEI',e,'renderHistory')}}
async function renderStock(){loading('Cargando Stock...');try{const r=await api('listStock');if(r.status==='error')throw Error(r.message);state.stock=r.data||[];document.querySelector('#app').innerHTML=`<section class="section stock-screen"><div class="section-head"><h2>📦 Stock</h2><div><button class="btn secondary" onclick="renderStock()">🔄 Actualizar</button><button class="btn secondary" onclick="exportRows(window.__stockFiltered||state.stock,'stock')">📄 Excel</button></div></div><div class="stock-tabs"><button class="btn active">📦 Stock Vivo</button><button class="btn secondary">🟦 Stock Mod. A</button><button class="btn secondary">🟧 Stock Mod. B</button></div><div class="section-body"><div class="toolbar"><input class="input" id="stock-q" placeholder="Buscar IMEI, cuenta, marca, modelo..."><select class="select" id="stock-cuenta"><option value="">Cuenta</option></select><select class="select" id="stock-marca"><option value="">Marca</option></select><select class="select" id="stock-modelo"><option value="">Modelo</option></select><select class="select" id="stock-inv"><option value="">En Inventario</option><option>SI</option><option>NO</option><option>NO VIVO</option></select><select class="select" id="stock-state"><option value="">Estado Inventario</option>${LDU_STATES.map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="stock-layout"><section class="section stock-panel"><div class="table-wrap module-table"><table><thead><tr><th>Cuenta</th><th>IMEI</th><th>Marca</th><th>Modelo</th><th>Monto S/</th><th>Fecha de ingreso</th><th>En Inventario</th><th>Estado Inventario</th><th>#Guia</th><th>Observaciones</th><th>Acc.</th></tr></thead><tbody id="stock-body"></tbody></table></div></section><section class="section stock-panel"><div class="section-head"><h2>📋 Panel del Equipo</h2></div><div id="stock-detail" class="empty">Selecciona un IMEI para ver sus movimientos.</div></section></div></section>`;const add=(id,k)=>{document.querySelector('#'+id).innerHTML+=Array.from(new Set(state.stock.map(x=>x[k]).filter(Boolean))).map(v=>`<option>${safe(v)}</option>`).join('')};add('stock-cuenta','cuenta');add('stock-marca','marca');add('stock-modelo','modelo');const draw=()=>{const q=document.querySelector('#stock-q').value.toLowerCase();const out=state.stock.filter(x=>(!q||Object.values(x).join(' ').toLowerCase().includes(q))&&(!document.querySelector('#stock-cuenta').value||norm(x.cuenta)===norm(document.querySelector('#stock-cuenta').value))&&(!document.querySelector('#stock-marca').value||norm(x.marca)===norm(document.querySelector('#stock-marca').value))&&(!document.querySelector('#stock-modelo').value||norm(x.modelo)===norm(document.querySelector('#stock-modelo').value))&&(!document.querySelector('#stock-inv').value||norm(x.en_inventario)===norm(document.querySelector('#stock-inv').value))&&(!document.querySelector('#stock-state').value||norm(x.estado_inventario)===norm(document.querySelector('#stock-state').value)));window.__stockFiltered=out;document.querySelector('#stock-body').innerHTML=out.map(x=>`<tr><td>${safe(x.cuenta)}</td><td><button class="link-button" data-stock-imei="${safe(x.imei)}">${safe(x.imei)}</button></td><td>${safe(x.marca)}</td><td>${safe(x.modelo)}</td><td>S/ ${safe(x.monto)}</td><td>${safe(displayImportValue(x.fecha_ingreso,'fecha_ingreso'))}</td><td>${safe(x.en_inventario)}</td><td>${badge(x.estado_inventario)}</td><td>${safe(x.guia)}</td><td>${safe(x.observaciones)}</td><td class="row-actions"><button data-stock-action="view" data-id="${safe(x.imei)}">👁️</button><button data-stock-action="history" data-id="${safe(x.imei)}">📜</button><button data-stock-action="edit" data-id="${safe(x.imei)}">✎️</button><button data-stock-action="delete" data-id="${safe(x.imei)}">✕</button></td></tr>`).join('')||'<tr><td colspan="11" class="empty">Sin resultados</td></tr>';document.querySelectorAll('[data-stock-imei]').forEach(b=>b.onclick=()=>{const x=state.stock.find(s=>String(s.imei)===String(b.dataset.stockImei));document.querySelector('#stock-detail').innerHTML=Object.entries(x||{}).map(([k,v])=>`<div class="detail-row"><b>${safe(k)}</b>${safe(displayImportValue(v,k))}</div>`).join('')});document.querySelectorAll('[data-stock-action]').forEach(b=>b.onclick=()=>{const x=out.find(s=>String(s.imei)===String(b.dataset.id));if(b.dataset.stockAction==='view')showDetail(x);else if(b.dataset.stockAction==='history'){state.historyImei=b.dataset.id;navigate('history')}else alert('La edición y eliminación de Stock se gestionan mediante una nueva importación para conservar el Kardex.')});};['stock-q','stock-cuenta','stock-marca','stock-modelo','stock-inv','stock-state'].forEach(id=>document.querySelector('#'+id).oninput=draw);draw()}catch(e){errorView('No se pudo cargar Stock',e,'renderStock')}}
async function previewImport(file,module,card){const msg=card.querySelector('[data-message]');try{const book=XLSX.read(await file.arrayBuffer(),{type:'array'}),rawRows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:''}),rows=canonicalizeImportRows(rawRows,module);if(!rows.length)throw Error('El archivo no contiene registros.');const drawer=document.createElement('div');drawer.className='drawer';const cols=Object.keys(rows[0]);drawer.innerHTML=`<aside class="drawer-card import-preview-card"><div class="section-head"><h2>📋 Vista previa — ${safe(file.name)}</h2><button class="btn secondary" id="close">✕</button></div><p>Registros detectados: <strong>${rows.length}</strong></p>${table(rows.slice(0,10),cols)}<progress id="import-progress" max="100" value="0" style="width:100%"></progress><div id="import-progress-text">Listo para importar.</div><div id="import-result"></div><div class="form-actions"><button class="btn secondary" id="cancel">Cancelar</button><button class="btn" id="confirm">📥 Importar</button></div></aside>`;document.body.appendChild(drawer);const close=()=>drawer.remove();drawer.querySelector('#close').onclick=close;drawer.querySelector('#cancel').onclick=close;drawer.querySelector('#confirm').onclick=async()=>{const out=drawer.querySelector('#import-result'),progress=drawer.querySelector('#import-progress'),progressText=drawer.querySelector('#import-progress-text'),button=drawer.querySelector('#confirm');button.disabled=true;let imported=0,updated=0,rejected=0;const batchSize=10,totalBatches=Math.ceil(rows.length/batchSize);for(let start=0,batchNo=1;start<rows.length;start+=batchSize,batchNo++){const batch=rows.slice(start,start+batchSize);try{const r=await api('importRows',{module,rows:batch,userId:'importacion'});if(r.status==='ok'){imported+=r.data?.imported||0;updated+=r.data?.updated||0;rejected+=r.data?.rejected||0}else rejected+=batch.length}catch(e){rejected+=batch.length}const done=Math.min(start+batch.length,rows.length);progress.value=Math.round(done*100/rows.length);progressText.textContent=`Procesando lote ${batchNo} de ${totalBatches} · ${done} de ${rows.length} registros`;out.textContent=`Nuevos: ${imported} · Actualizados: ${updated} · Rechazados: ${rejected}`;}button.disabled=false;if(!rejected){progress.value=100;progressText.textContent='✅ Importación completada';setTimeout(()=>{close();navigate(module===1?'incidents':module>=2?'stock':'inventory')},700)}};}catch(e){msg.textContent='Error: '+e.message}}


async function renderIncidents(){loading('Cargando incidencias...');try{const r=await api('listIncidents');if(r.status==='error')throw Error(r.message);state.incidents=r.data||[];const byType=k=>state.incidents.filter(x=>norm(x.tipo)===norm(k)).length;const byProcess=k=>state.incidents.filter(x=>norm(x.estado_proceso)===norm(k)).length;const totalValue=state.incidents.reduce((n,x)=>n+Number(x.valor||0),0);document.querySelector('#app').innerHTML=`<section class="section incidents-screen"><div class="section-head"><h2>⚠️ Incidencias</h2><div><button class="btn secondary" onclick="renderIncidents()">🔄 Actualizar</button><button class="btn secondary" onclick="exportRows(state.incidents,'incidencias')">📄 Excel</button><button class="btn" onclick="openIncidentForm()">＋ Nueva</button></div></div><div class="cards incident-cards">${card('📊 TOTAL',state.incidents.length)}${card('⏳ PENDIENTE',byProcess('Pendiente'))}${card('🔄 EN CURSO',byProcess('En Curso'))}${card('💥 DAÑADOS',byType('Daño'))}${card('🔍 PERDIDOS',byType('Pérdida'))}${card('🕵️ ROBADOS',byType('Robo'))}${card('📌 OTROS',byType('Otro'))}${card('🔁 REPOSICIÓN',byType('Reposición'))}${card('↩️ DEVOLUCIÓN',byType('Devolución'))}${card('💰 VALOR TOTAL','S/ '+totalValue.toFixed(2))}</div>${table(state.incidents,['imei_original','tipo','imei_nuevo','marca','modelo','responsable','supervisor','fecha_incidente','valor','estado_proceso'])}</section>`}catch(e){errorView('No se pudo cargar Incidencias',e,'renderIncidents')}}
